def get_map_spawns(arenaTypeID):

    key = str(arenaTypeID).strip()
    geom = key if key.startswith('spaces/') else ('spaces/' + key)
    short = key[7:] if key.startswith('spaces/') else key
    return SPAWN_POINTS.get(geom) or SPAWN_POINTS.get(short)
